scripts.home:
// GET /  The packages by category and how it works.
function handle(req) {
  const lang = langOf(req), groups = [], byName = {};
  for (const p of db.query('SELECT * FROM packages WHERE active = 1 ORDER BY id')) {
    const v = packageView(p, lang);
    if (!byName[p.category]) groups.push(byName[p.category] = {name: v.category, packages: []});
    byName[p.category].packages.push(v);
  }
  return {template: 'home', data: page(req, {groups: groups})};
}

scripts.package:
// GET /packages/:id  One package with the enquiry form (for signed-in visitors).
function handle(req) {
  const p = db.query('SELECT * FROM packages WHERE id = ? AND active = 1', Number(req.params.id))[0];
  if (!p) return notFound(req);
  const u = req.user, v = packageView(p, langOf(req));
  return {template: 'package', data: page(req, {pkg: v, title: v.name, buybar: true,
    form: formOf({package_id: p.id, name: u && u.name, email: u && u.email, phone: u && u.phone})})};
}

scripts.enquiry_form:
// GET /enquiry  Free-form enquiry (signed in). ?package=ID preselects a package.
function handle(req) {
  const lang = langOf(req), u = req.user;
  const packages = db.query('SELECT * FROM packages WHERE active = 1 ORDER BY id').map(p => packageView(p, lang));
  return {template: 'enquiry', data: page(req, {packages: packages,
    form: formOf({package_id: req.query.package, name: u.name, email: u.email, phone: u.phone})})};
}

scripts.enquiry:
// POST /enquiry (signed in)  Stores the enquiry and tells the owner. On a mistake the form comes back with what was typed.
function handle(req) {
  const lang = langOf(req), f = req.form;
  const form = {package_id: clip(f.package_id, 10), name: clip(f.name, 100), company: clip(f.company, 150), phone: clip(f.phone, 30),
    email: clip(f.email, 200).toLowerCase(), message: clip(f.message, 3000), target_date: clip(f.target_date, 60), budget: clip(f.budget, 60)};
  const again = (key) => {
    const packages = db.query('SELECT * FROM packages WHERE active = 1 ORDER BY id').map(p => packageView(p, lang));
    return {template: 'enquiry', data: page(req, {packages: packages, form: form, error: texts(lang)[key]}), status: 422};
  };
  let pkg = null;
  if (form.package_id) {
    pkg = db.query('SELECT * FROM packages WHERE id = ? AND active = 1', Number(form.package_id))[0];
    if (!pkg) form.package_id = '';
  }
  if (!form.name || !form.phone || (!pkg && !form.message)) return again('error_fields');
  if (form.email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(form.email)) return again('error_email');
  const since = new Date(Date.now() - 86400000).toISOString().replace('T', ' ').slice(0, 19);
  if (db.query('SELECT COUNT(*) AS n FROM enquiries WHERE user_id = ? AND created_at >= ?', req.user.id, since)[0].n >= 5) return again('error_many');
  const id = db.exec(`INSERT INTO enquiries (user_id, client_name, company, phone, email, package_id, message, target_date, budget, status, lang)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'new', ?)`, req.user.id, form.name, form.company, form.phone, form.email, pkg ? pkg.id : null,
    form.message, form.target_date, form.budget, lang).lastInsertId;
  tellOwner('New enquiry #' + id + ': ' + (pkg ? pkg.name : 'custom request') + ' from ' + form.name + ', ' + form.phone,
    'Client: ' + form.name + (form.company ? ' (' + form.company + ')' : '') + '\nPhone: ' + form.phone + '\nEmail: ' + (form.email || '-') +
    '\nPackage: ' + (pkg ? pkg.name : '-') + '\nTarget date: ' + (form.target_date || '-') + '\nBudget: ' + (form.budget || '-') +
    '\n\n' + (form.message || '') + '\n\nTo answer, add a quote with enquiry number ' + id + ' in the admin panel (Quotes) and set its status to sent.');
  return {redirect: '/portal?done=done_enquiry' + (lang === 'ar' ? '&lang=ar' : '')};
}

scripts.portal:
// GET /portal (signed in)  The visitor's own enquiries with their quotes.
function handle(req) {
  const lang = langOf(req), t = texts(lang), b = biz();
  const enquiries = db.query(`SELECT e.*, p.name AS package_name, p.name_ar AS package_name_ar FROM enquiries e LEFT JOIN packages p ON p.id = e.package_id
    WHERE e.user_id = ? ORDER BY e.id DESC LIMIT 50`, req.user.id);
  const quotes = db.query(`SELECT q.* FROM quotes q JOIN enquiries e ON e.id = q.enquiry_id
    WHERE e.user_id = ? AND q.status <> 'draft' ORDER BY q.id DESC LIMIT 100`, req.user.id);
  const paid = {};
  for (const r of db.query(`SELECT p.quote_id, SUM(p.amount - coalesce(p.refunded_amount, 0)) AS n FROM quote_payments p JOIN quotes q ON q.id = p.quote_id
    JOIN enquiries e ON e.id = q.enquiry_id WHERE e.user_id = ? AND p.status = 'paid' GROUP BY p.quote_id`, req.user.id)) paid[r.quote_id] = round2(r.n);
  const byEnquiry = {};
  for (const q of quotes) {
    const st = quoteState(q, b, paid[q.id] || 0);
    const when = dubaiTime(q.created_at, t);
    (byEnquiry[q.enquiry_id] = byEnquiry[q.enquiry_id] || []).push({id: q.id, number: fill(t.quote_no, {id: q.id}), title: q.title, status: st.status,
      statusText: t['status_' + st.status] || st.status, total: st.ok ? price(st.total, t) : '', day: when.day, date: longDate(when.day, t)});
  }
  const list = enquiries.map(e => {
    const qs = byEnquiry[e.id] || [];
    const status = e.status === 'new' && qs.length ? 'quoted' : e.status;
    const when = dubaiTime(e.created_at, t);
    return {id: e.id, number: fill(t.enquiry_no, {id: e.id}), title: e.package_name ? (lang === 'ar' && e.package_name_ar ? e.package_name_ar : e.package_name) : t.custom_enquiry,
      message: e.message || '', day: when.day, date: longDate(when.day, t), status: status, statusText: t['enquiry_' + status] || status, quotes: qs};
  });
  const done = req.query.done === 'done_enquiry' ? t.done_enquiry : '';
  return {template: 'portal', data: page(req, {title: t.my_portal, enquiries: list, flash: done})};
}

scripts.quote:
// GET /quotes/:id (signed in; own quotes)  Lines, VAT, accept or decline, payments, updates and messages.
function handle(req) {
  const lang = langOf(req), t = texts(lang), b = biz(), id = Number(req.params.id);
  const q = ownQuote(id, req.user.id);
  if (!q) return notFound(req);
  const st = quoteState(q, b);
  const flash = /^done_\w+$/.test(req.query.done || '') ? req.query.done : '', error = /^error_\w+$/.test(req.query.error || '') ? t[req.query.error] : '';
  const messages = db.query('SELECT sender, text, created_at FROM messages WHERE quote_id = ? ORDER BY id DESC LIMIT 100', id).reverse()
    .map(m => { const w = dubaiTime(m.created_at, t); return {firm: m.sender === 'firm', text: m.text, stamp: w.day, date: w.text}; });
  // The client's documents; each file opens only for the client who uploaded it (and for the owner in the admin panel).
  const documents = db.query('SELECT file, label, created_at FROM documents WHERE quote_id = ? ORDER BY id LIMIT ?', id, MAX_DOCUMENTS).map(d => {
    const f = files.get(d.file);
    return {label: t['doc_' + d.label] || d.label, name: f ? f.name : t.doc_missing, url: f && f.user_id === req.user.id ? files.url(d.file) : '',
      day: dubaiTime(d.created_at, t).day, date: longDate(dubaiTime(d.created_at, t).day, t)};
  });
  const docs = {documents: documents, canUpload: documents.length < MAX_DOCUMENTS, docLabels: DOC_LABELS.map(v => ({value: v, label: t['doc_' + v]}))};
  if (!st.ok) {
    // The owner's lines cannot be read: say so kindly instead of failing, and leave a trace for the owner's agent.
    console.warn('quote ' + id + ' has lines that cannot be read; expected [{"name": "...", "qty": 1, "price": 1500}]');
    return {template: 'quote', data: page(req, {q: {id: id, number: fill(t.quote_no, {id: id}), title: q.title, broken: true, status: q.status, statusText: t['status_' + q.status] || q.status},
      title: fill(t.quote_no, {id: id}),
      messages: messages, error: error, notice: flash ? t[flash] : '', clientName: q.client_name, ...docs})};
  }
  syncQuote(q, st);
  const rows = db.query('SELECT * FROM quote_payments WHERE quote_id = ? ORDER BY id', id);
  let waiting = null, failed = false;
  for (const p of rows) {
    if (p.stage !== st.stage) continue;
    if (p.method === 'transfer' && p.status === 'pending') waiting = {amount: price(p.amount, t), reference: p.reference};
    if (p.method === 'card') failed = p.status === 'failed' || p.status === 'expired';
  }
  let notice = flash ? t[flash] : '';
  if (flash === 'done_paid') {
    // Do not trust the address: say thank you only when the ledger shows the payment.
    const last = rows.filter(p => p.method === 'card').pop();
    if (!last || last.status !== 'paid') {
      const pay = last ? payments.get(last.reference) : null;
      notice = pay && (pay.status === 'paid' || pay.status === 'pending') ? t.pay_processing : '';
    }
  }
  const canPay = st.stage !== '' && (st.stage === 'deposit' || q.balance_due === 1);
  const accepted = dubaiTime(q.accepted_at, t);
  const view = {id: id, number: fill(t.quote_no, {id: id}), title: q.title, status: st.status, statusText: t['status_' + st.status] || st.status,
    lines: st.lines.map(l => ({name: l.name, qty: l.qty === 1 ? '' : String(l.qty), each: l.qty === 1 ? '' : fill(t.each, {price: price(l.price, t)}),
      line: price(l.qty * l.price, t)})),
    subtotal: price(st.subtotal, t), vat: price(st.vat, t), total: price(st.total, t), inclusive: st.inclusive, until: st.until, untilText: longDate(st.until, t),
    notes: loc(q, 'notes', lang), pct: st.pct, deposit: st.deposit > 0 && st.deposit < st.total ? price(st.deposit, t) : '',
    accepted: st.accepted, acceptedDay: accepted.day, acceptedDate: longDate(accepted.day, t),
    acceptedLine: fill(t.accepted_line, {name: iso(q.accepted_name, lang), when: accepted.text}),
    paid: price(st.paid, t), balance: price(st.total - st.paid, t), stage: st.stage, stageText: st.stage ? t['stage_' + st.stage] : '',
    dueLine: st.stage ? fill(t.due_line, {stage: t['stage_' + st.stage], amount: price(st.due, t)}) : '',
    canAccept: st.status === 'sent', canPay: canPay, notDue: st.stage === 'balance' && !canPay,
    card: canPay && b.card_enabled === 1, transfer: canPay && !!b.bank_details && !waiting, waiting: waiting, bank: waiting ? b.bank_details : '',
    failed: failed && canPay};
  let refunded = 0;
  const pays = rows.filter(p => p.status === 'paid' || p.status === 'refunded' || (p.status === 'pending' && p.method === 'transfer')).map(p => {
    // A refunded payment keeps the amount paid; refunded_amount is what went back (all of it when the status is refunded).
    const back = p.status === 'refunded' ? p.refunded_amount || p.amount : p.refunded_amount || 0;
    refunded += back;
    const status = p.status === 'paid' && back > 0 ? 'partially_refunded' : p.status;
    const when = dubaiTime(p.paid_at || p.created_at, t);
    return {id: p.id, stageText: t['stage_' + p.stage] || p.stage, amount: price(p.amount, t), methodText: t['method_' + p.method] || p.method,
      statusText: t['payment_' + status] || status, paid: p.status === 'paid', refunded: back > 0 ? price(back, t) : '', day: when.day, date: longDate(when.day, t)};
  });
  view.refunded = refunded > 0 ? price(refunded, t) : '';
  view.showPayments = st.accepted || pays.length > 0;
  const updates = db.query('SELECT title, text, link, created_at FROM updates WHERE quote_id = ? AND visible = 1 ORDER BY id DESC LIMIT 100', id)
    .map(u => { const w = dubaiTime(u.created_at, t); return {title: u.title, text: u.text || '', link: /^https?:\/\//.test(u.link || '') ? u.link : '', day: w.day, date: longDate(w.day, t)}; });
  return {template: 'quote', data: page(req, {title: view.number, q: view, payments: pays, updates: updates, messages: messages, notice: notice, error: error,
    clientName: q.client_name, ...docs})};
}

scripts.accept:
// POST /quotes/:id/accept (signed in; own quotes)  Acceptance is a recorded click: the typed name, the time and the account.
// The lines and totals are stored as accepted, so later edits in the admin panel do not change what the client agreed to.
function handle(req) {
  const lang = langOf(req), b = biz(), id = Number(req.params.id);
  const q = ownQuote(id, req.user.id);
  if (!q) return notFound(req);
  const st = quoteState(q, b);
  if (!st.ok) return back(id, lang, 'error', 'error_unavailable');
  if (st.status === 'expired') return back(id, lang, 'error', 'error_expired');
  if (st.status !== 'sent') return back(id, lang, 'error', 'error_not_open');
  const name = clip(req.form.name, 100);
  if (!name || req.form.agree !== '1') return back(id, lang, 'error', 'error_accept');
  const r = db.exec(`UPDATE quotes SET status = 'accepted', accepted_at = ?, accepted_name = ?, accepted_by = ?, accepted_lines = ?, subtotal = ?, vat = ?,
    total = ?, deposit_amount = ?, paid_amount = 0, valid_until = ? WHERE id = ? AND status = 'sent'`,
    nowUTC(), name, req.user.id, JSON.stringify(st.lines), st.subtotal, st.vat, st.total, st.deposit, st.until, id);
  if (r.rowsAffected === 0) return back(id, lang, 'error', 'error_not_open');
  db.exec("UPDATE enquiries SET status = 'won' WHERE id = ?", q.enquiry_id);
  tellOwner('Quote #' + id + ' accepted by ' + name + ': AED ' + money(st.total),
    q.title + '\nAccepted by ' + name + ' (' + q.client_name + ', ' + (q.client_phone || '-') + ')\nTotal: AED ' + money(st.total) +
    ' including VAT AED ' + money(st.vat) + '\nDeposit: AED ' + money(st.deposit) + '\n\n' + quoteLink(req, id, 'en'));
  mailClient(q.client_email, lang, 'email_accepted', {id: id, title: q.title, name: q.client_name, total: st.total,
    deposit: st.deposit, link: quoteLink(req, id, lang)});
  return back(id, lang, 'done', 'done_accepted');
}

