scripts.pay:
// POST /quotes/:id/pay (signed in; own quotes)  form: method = card | transfer.
// Pays what is due now: the deposit after acceptance, the balance once the owner has asked for it. The amount is always
// worked out here, never taken from the browser.
function handle(req) {
  const lang = langOf(req), t = texts(lang), b = biz(), id = Number(req.params.id);
  const q = ownQuote(id, req.user.id);
  if (!q) return notFound(req);
  const st = quoteState(q, b);
  if (!st.ok || !st.accepted) return back(id, lang, 'error', 'error_unavailable');
  if (st.stage === '') return back(id, lang, 'done', 'done_paid');
  if (st.stage === 'balance' && q.balance_due !== 1) return back(id, lang, 'error', 'error_not_due');
  if (req.form.method === 'transfer') {
    if (!b.bank_details) return back(id, lang, 'error', 'error_payment');
    const old = db.query("SELECT id FROM quote_payments WHERE quote_id = ? AND stage = ? AND method = 'transfer' AND status = 'pending'", id, st.stage)[0];
    if (old) db.exec('UPDATE quote_payments SET amount = ? WHERE id = ?', st.due, old.id);
    else {
      db.exec("INSERT INTO quote_payments (quote_id, stage, amount, method, status, reference, notified) VALUES (?, ?, ?, 'transfer', 'pending', ?, 0)",
        id, st.stage, st.due, 'Q' + id + '-' + st.stage);
      tellOwner('Bank transfer announced: AED ' + money(st.due) + ' (' + st.stage + ') for quote #' + id + ', ' + q.client_name,
        q.title + '\nThe client will pay AED ' + money(st.due) + ' by bank transfer with reference Q' + id + '-' + st.stage +
        '.\nWhen the money is in your account, open Payments in the admin panel and set this payment to paid.');
    }
    return back(id, lang, 'done', 'done_transfer');
  }
  if (b.card_enabled !== 1) return back(id, lang, 'error', 'error_payment');
  // One card row per stage: a failed or abandoned attempt is tried again on the same row.
  const reference = 'quote-' + id + '-' + st.stage;
  const row = db.query("SELECT id FROM quote_payments WHERE quote_id = ? AND stage = ? AND method = 'card' AND status IN ('pending', 'failed', 'expired') ORDER BY id DESC",
    id, st.stage)[0];
  let rowId;
  if (row) { rowId = row.id; db.exec("UPDATE quote_payments SET status = 'pending', amount = ? WHERE id = ?", st.due, rowId); }
  else rowId = db.exec("INSERT INTO quote_payments (quote_id, stage, amount, method, status, reference, notified) VALUES (?, ?, ?, 'card', 'pending', ?, 0)",
    id, st.stage, st.due, reference).lastInsertId;
  try {
    const pay = payments.checkout({items: [{name: t['stage_' + st.stage] + ': ' + q.title + ' (#' + id + ')', price: st.due, quantity: 1}],
      reference: reference, customer_email: q.client_email || req.user.email || '',
      success_path: '/quotes/' + id + '?done=done_paid' + (lang === 'ar' ? '&lang=ar' : ''), cancel_path: '/quotes/' + id + (lang === 'ar' ? '?lang=ar' : '')});
    return {redirect: pay.url};
  } catch (e) {
    console.error('checkout failed for quote ' + id + ': ' + e);
    db.exec("UPDATE quote_payments SET status = 'failed' WHERE id = ?", rowId);
    return back(id, lang, 'error', 'error_payment');
  }
}

scripts.message:
// POST /quotes/:id/message (signed in; own quotes)  A short message to the firm: at most 1000 characters, 20 a day per quote.
function handle(req) {
  const lang = langOf(req), id = Number(req.params.id);
  const q = ownQuote(id, req.user.id);
  if (!q) return notFound(req);
  const text = String(req.form.text || '').trim();
  if (!text || text.length > 1000) return back(id, lang, 'error', 'error_message');
  const since = new Date(Date.now() - 86400000).toISOString().replace('T', ' ').slice(0, 19);
  if (db.query("SELECT COUNT(*) AS n FROM messages WHERE quote_id = ? AND sender = 'client' AND created_at >= ?", id, since)[0].n >= 20) {
    return back(id, lang, 'error', 'error_many_messages');
  }
  db.exec("INSERT INTO messages (quote_id, user_id, sender, text, notified) VALUES (?, ?, 'client', ?, 1)", id, req.user.id, text);
  tellOwner('Message on quote #' + id + ' from ' + q.client_name + ': ' + text.replace(/\s+/g, ' ').slice(0, 80),
    text + '\n\n' + q.title + '\nPhone: ' + (q.client_phone || '-') + '\nTo reply, add a row in Messages in the admin panel with quote number ' + id + ' and From = firm.');
  return back(id, lang, 'done', 'done_message');
}

scripts.invoice:
// GET /quotes/:id/invoice/:payment (signed in; own quotes)  Printable receipt for one paid stage; a UAE tax invoice once the TRN is set.
// The payment is split into net and VAT in the proportion of the accepted quote.
function handle(req) {
  const lang = langOf(req), t = texts(lang), b = biz(), id = Number(req.params.id);
  const q = ownQuote(id, req.user.id);
  if (!q) return notFound(req);
  const p = db.query("SELECT * FROM quote_payments WHERE id = ? AND quote_id = ? AND status = 'paid'", Number(req.params.payment), id)[0];
  const st = quoteState(q, b);
