  const net = round2(p.amount * st.subtotal / st.total);
  const day = dubaiDate(new Date((p.paid_at || p.created_at).replace(' ', 'T') + 'Z').getTime());
  return {template: 'invoice', data: page(req, {inv: {title: b.trn ? t.tax_invoice : t.receipt, number: 'INV-' + id + '-' + p.id,
    day: day, date: longDate(day, t), quoteId: id, quoteNo: fill(t.quote_no, {id: id}),
    seller: loc(b, 'legal_name', lang) || loc(b, 'name', lang), sellerAddress: loc(b, 'address', lang), trn: b.trn || '', licence: loc(b, 'licence', lang),
    buyer: q.client_name, company: q.company || '', phone: q.client_phone || '', email: q.client_email || '',
    description: (t['stage_' + p.stage] || p.stage) + ': ' + iso(q.title, lang) + ' (' + fill(t.quote_no, {id: id}) + ')',
    method: t['method_' + p.method] || p.method, net: money(net), vat: money(p.amount - net), total: money(p.amount),
    netText: price(net, t), vatText: price(p.amount - net, t), totalText: price(p.amount, t),
    quoteTotal: price(st.total, t), paid: price(st.paid, t), balance: price(st.total - st.paid, t)}})};
}

scripts.on_payment:
// Runs when a card payment is paid, fails, expires or is refunded. req.body: {event, reference, amount, refunded_amount, ...}
// reference is quote-<quote id>-<stage>, the card row of that stage in the payments ledger.
function handle(req) {
  const m = /^quote-(\d+)-(deposit|balance)$/.exec(String(req.body.reference));
  if (!m) return {text: 'ignored'};
  const id = Number(m[1]), stage = m[2], event = req.body.event;
  const row = db.query("SELECT * FROM quote_payments WHERE quote_id = ? AND stage = ? AND method = 'card' ORDER BY id DESC", id, stage)[0];
  const q = db.query(`SELECT q.*, e.client_name AS client_name, e.email AS client_email, e.lang AS client_lang
    FROM quotes q JOIN enquiries e ON e.id = q.enquiry_id WHERE q.id = ?`, id)[0];
  if (!row || !q) return {text: 'ignored'};
  if (event === 'paid') {
    if (row.status === 'paid') return {text: 'ignored'};
    db.exec("UPDATE quote_payments SET status = 'paid', amount = ?, paid_at = ?, notified = 1 WHERE id = ?", req.body.amount, nowUTC(), row.id);
    // A transfer announced for the same stage is no longer expected.
    db.exec("UPDATE quote_payments SET status = 'expired' WHERE quote_id = ? AND stage = ? AND status = 'pending' AND id <> ?", id, stage, row.id);
    const lang = q.client_lang === 'ar' ? 'ar' : 'en';
    mailClient(q.client_email || req.body.customer_email, lang, 'email_payment', {id: id, title: q.title, name: q.client_name,
      amount: round2(req.body.amount), stage: texts(lang)['stage_' + stage], link: req.origin + '/quotes/' + id + '/invoice/' + row.id + (lang === 'ar' ? '?lang=ar' : '')});
  } else if (event === 'refunded' || event === 'partially_refunded') {
    // Money went back (payments.refund on cancellation, the Payments page or Stripe): the row keeps the amount paid and
    // records the total refunded, so the paid amount is what the business still holds. Refunded in full: status refunded.
    const total = round2(req.body.refunded_amount), more = round2(total - (row.refunded_amount || 0));
    db.exec('UPDATE quote_payments SET refunded_amount = ?, status = ? WHERE id = ?', total, event === 'refunded' ? 'refunded' : 'paid', row.id);
    if (more > 0) {
      const lang = q.client_lang === 'ar' ? 'ar' : 'en';
      mailClient(q.client_email || req.body.customer_email, lang, 'email_refund', {id: id, title: q.title, name: q.client_name,
        amount: more, stage: texts(lang)['stage_' + stage], link: quoteLink(req, id, lang)});
    }
  } else if (row.status === 'pending') {
    // Failed or expired: the stage stays unpaid and the client can pay again from the quote page.
    db.exec('UPDATE quote_payments SET status = ? WHERE id = ?', event === 'failed' ? 'failed' : 'expired', row.id);
  }
  const st = quoteState(q, biz());
  if (st.accepted) syncQuote(q, st);
  // A cancelled or declined quote keeps its status; its paid amount still follows the ledger (e.g. after a refund).
  else if (Math.abs((q.paid_amount || 0) - paidOf(id)) >= 0.005) db.exec('UPDATE quotes SET paid_amount = ? WHERE id = ?', paidOf(id), id);
  console.log('quote ' + id + ' ' + stage + ' payment ' + event);
  return {text: 'ok'};
}

