scripts.daily_summary:
// Job, every morning: quotes past their valid-until date expire, and the owner gets a summary of what waits for them
// (by email, and on WhatsApp if turned on).
function handle(req) {
  const b = biz(), today = dubaiDate(Date.now());
  let expired = 0;
  for (const q of db.query("SELECT * FROM quotes WHERE status = 'sent' ORDER BY id LIMIT 100")) {
    if (validUntil(q, b) < today) { db.exec("UPDATE quotes SET status = 'expired' WHERE id = ? AND status = 'sent'", q.id); expired++; }
  }
  const one = (sql) => db.query(sql)[0];
  const enquiries = one("SELECT COUNT(*) AS n FROM enquiries WHERE status = 'new'").n;
  const waiting = one("SELECT COUNT(*) AS n FROM quotes WHERE status = 'sent'").n;
  const drafts = one("SELECT COUNT(*) AS n FROM quotes WHERE status = 'draft'").n;
  const deposits = one("SELECT COUNT(*) AS n FROM quotes WHERE status = 'accepted'").n;
  const transfers = one("SELECT COUNT(*) AS n, coalesce(SUM(amount), 0) AS total FROM quote_payments WHERE status = 'pending' AND method = 'transfer'");
  if (enquiries + waiting + drafts + deposits + transfers.n + expired === 0) return {text: 'nothing to report'};
  const list = db.query("SELECT id, client_name, phone FROM enquiries WHERE status = 'new' ORDER BY id DESC LIMIT 10")
    .map(e => '#' + e.id + ' ' + e.client_name + ', ' + (e.phone || '-')).join('\n');
  const pending = db.query(`SELECT p.quote_id, p.stage, p.amount, p.reference FROM quote_payments p WHERE p.status = 'pending' AND p.method = 'transfer'
    ORDER BY p.id LIMIT 10`).map(p => 'Quote #' + p.quote_id + ' ' + p.stage + ': AED ' + money(p.amount) + ' (' + p.reference + ')').join('\n');
  tellOwner('Today: ' + enquiries + ' new enquir' + (enquiries === 1 ? 'y' : 'ies') + ', ' + waiting + ' quote' + (waiting === 1 ? '' : 's') +
    ' waiting for the client, AED ' + money(transfers.total) + ' in transfers to confirm',
    'New enquiries without a quote: ' + enquiries + (list ? '\n' + list : '') + '\nDraft quotes not sent yet: ' + drafts +
    '\nQuotes waiting for the client: ' + waiting + '\nAccepted, deposit not paid yet: ' + deposits +
    '\nBank transfers to confirm: ' + transfers.n + ', AED ' + money(transfers.total) + (pending ? '\n' + pending : '') +
    '\nQuotes expired today: ' + expired);
  return {text: enquiries + ' new enquiries, ' + waiting + ' quotes waiting, ' + transfers.n + ' transfers pending, ' + expired + ' expired'};
}

