scripts.admin_change:
// on_admin_change: runs right after the owner or staff adds, changes or deletes a row in the admin panel, so clients
// are emailed at once (quote sent, balance asked for, update posted, reply, transfer marked paid), and a cancelled quote's
// card payments are refunded when the owner ticks "Refund card payments when cancelled".
function handle(req) {
  const b = req.body;
  if (b.action === 'delete' || ['quotes', 'quote_payments', 'updates', 'messages'].indexOf(b.table) < 0) return {text: 'nothing to do'};
  const refund = b.table === 'quotes' && b.row && b.row.status === 'cancelled' ? cancelled(req, b.row, b.before) : '';
  return {text: notifyClients(req) + ' emails sent' + refund};
}

// A cancelled quote: the card payments it still holds are refunded in full only when refund_on_cancel is ticked (when
// cancelling, or later); otherwise the money stays recorded as paid in the ledger and the owner can refund all or part of it
// on the Payments page. Bank transfers are never refunded here. Each refund is recorded in the ledger and emailed to the client
// right here; on_payment, which also gets the refund event, then finds it already recorded and changes nothing.
function cancelled(req, q, before) {
  const cards = db.query("SELECT * FROM quote_payments WHERE quote_id = ? AND method = 'card' AND status = 'paid' ORDER BY id", q.id)
    .filter(p => round2(p.amount - (p.refunded_amount || 0)) > 0);
  const held = round2(cards.reduce((s, p) => s + p.amount - (p.refunded_amount || 0), 0));
  if (!(held > 0)) return '';
  if (q.refund_on_cancel !== 1) {
    if (!before || before.status !== 'cancelled') console.log('quote ' + q.id + ' cancelled; AED ' + money(held) + ' paid by card is kept (refund_on_cancel is off)');
    return ', AED ' + money(held) + ' paid by card not refunded';
  }
  const c = db.query('SELECT client_name, email, lang FROM enquiries WHERE id = ?', q.enquiry_id)[0] || {};
  const lang = c.lang === 'ar' ? 'ar' : 'en';
  let done = 0;
  for (const p of cards) {
    let r;
    try {
      r = payments.refund({reference: p.reference, reason: 'Quote #' + q.id + ' cancelled'});
    } catch (e) {
      console.warn('refund of ' + p.reference + ' not made: ' + e);
      continue;
    }
    const more = round2(r.refunded_amount - (p.refunded_amount || 0));
    done = round2(done + more);
    db.exec('UPDATE quote_payments SET refunded_amount = ?, status = ? WHERE id = ?', round2(r.refunded_amount), r.status === 'refunded' ? 'refunded' : 'paid', p.id);
    mailClient(c.email, lang, 'email_refund', {id: q.id, title: q.title, name: c.client_name || '', amount: more,
      stage: texts(lang)['stage_' + p.stage], link: quoteLink(req, q.id, lang)});
  }
  db.exec('UPDATE quotes SET paid_amount = ? WHERE id = ?', paidOf(q.id), q.id);
  if (done < held) tellOwner('Refund not made for cancelled quote #' + q.id + ': AED ' + money(held - done),
    'Some card payments of quote #' + q.id + ' (' + q.title + ') could not be refunded; see the app log. Refund them on the Payments page.');
  return ', AED ' + money(done) + ' refunded';
}

scripts.document:
// POST /quotes/:id/documents (signed in; own quotes)  form: label (passport | emirates_id | trade_licence | other) and file, the id of
// a private upload (/_rx/upload, sent by /_rx/upload.js). Only the client who uploaded a file can attach it; at most 20 per quote.
// The owner and staff open the files from Client documents in the admin panel; nobody else can.
function handle(req) {
  const lang = langOf(req), id = Number(req.params.id);
  const q = ownQuote(id, req.user.id);
  if (!q) return notFound(req);
  const label = DOC_LABELS.indexOf(req.form.label) >= 0 ? req.form.label : 'other';
  // The id comes from the browser: accept only a file this visitor uploaded.
  const f = req.form.file ? files.get(String(req.form.file)) : null;
  if (!f || f.user_id !== req.user.id) return back(id, lang, 'error', 'error_document');
  if (db.query('SELECT COUNT(*) AS n FROM documents WHERE quote_id = ? AND file = ?', id, f.id)[0].n > 0) return back(id, lang, 'done', 'done_document');
  if (db.query('SELECT COUNT(*) AS n FROM documents WHERE quote_id = ?', id)[0].n >= MAX_DOCUMENTS) return back(id, lang, 'error', 'error_many_documents');
  db.exec('INSERT INTO documents (quote_id, user_id, file, label) VALUES (?, ?, ?, ?)', id, req.user.id, f.id, label);
  const what = texts('en')['doc_' + label] || label;
  tellOwner('New document on quote #' + id + ' from ' + q.client_name + ': ' + what,
    what + ': ' + f.name + ' (' + Math.ceil(f.size / 1024) + ' KB)\n' + q.title + '\nOpen it in the admin panel, Client documents (quote number ' + id + ').');
  return back(id, lang, 'done', 'done_document');
}

lib.theme:
// Merchant branding from the settings row (brand_color, font, logo), shared by every Renoxium template.
// theme(row) returns {brand, onBrand, brandText, font, style, lux, logo}; the "top" template puts them on <html>
// (data-font, data-style and CSS variables).
// brand: the owner's colour (#rrggbb); when it is empty or not a colour, a quiet slate (or a deep ink for the luxury styles).
// onBrand: white or near-black, whichever reads better on brand (buttons, the intro band).
// brandText: brand darkened until it passes WCAG AA (4.5:1) as text on white, for links and selected states.
// font picks the type pair and the style:
//   modern (IBM Plex Sans + IBM Plex Sans Arabic), classic (Markazi Text headings + IBM Plex), rounded (Rubik): style "standard".
//   heritage (Cormorant Garamond + Jost, Amiri + Noto Naskh Arabic; ivory, antique gold hairlines) and
//   atelier (Bodoni Moda + Hanken Grotesk, Noto Naskh Arabic + Noto Kufi Arabic; white, near monochrome): style "luxury",
//   which switches to the luxury layout (centred name, full-bleed photo, no boxes, square buttons).
const THEME_DEFAULT_BRAND = '#334155';
const THEME_DEFAULT_INK = '#1f1b17';
const THEME_FONTS = ['modern', 'classic', 'rounded', 'heritage', 'atelier'];
const THEME_LUXURY = ['heritage', 'atelier'];
function themeHex(v) {
  let s = String(v || '').trim().toLowerCase();
  if (/^#?[0-9a-f]{3}$/.test(s)) s = s.replace('#', '').split('').map(c => c + c).join('');
  s = s.replace('#', '');
  return /^[0-9a-f]{6}$/.test(s) ? '#' + s : '';
}
function themeRgb(hex) { return [1, 3, 5].map(i => parseInt(hex.slice(i, i + 2), 16)); }
function themeLum(rgb) {
  const c = rgb.map(v => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); });
  return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
}
function themeContrast(a, b) { const x = themeLum(a), y = themeLum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); }
function themeToHex(rgb) { return '#' + rgb.map(v => (Math.round(v) < 16 ? '0' : '') + Math.round(v).toString(16)).join(''); }
function theme(row) {
  row = row || {};
  const font = THEME_FONTS.indexOf(row.font) >= 0 ? row.font : 'modern';
  const lux = THEME_LUXURY.indexOf(font) >= 0;
  const brand = themeHex(row.brand_color) || (lux ? THEME_DEFAULT_INK : THEME_DEFAULT_BRAND);
  const rgb = themeRgb(brand), white = [255, 255, 255], ink = [26, 23, 22];
  const onBrand = themeContrast(rgb, white) >= themeContrast(rgb, ink) ? '#ffffff' : '#1a1716';
  let text = rgb;
  for (let i = 0; i < 20 && themeContrast(text, white) < 4.5; i++) text = text.map(v => v * 0.9);
  return {brand: brand, onBrand: onBrand, brandText: themeToHex(text), font: font, style: lux ? 'luxury' : 'standard', lux: lux, logo: row.logo || ''};
}

lib.common:
// Helpers shared by every script of the portal (lib entries run before each script).
function langOf(req) { return (req.query.lang || (req.form && req.form.lang)) === 'ar' ? 'ar' : 'en'; }
const textCache = {};
function texts(lang) {
  if (textCache[lang]) return textCache[lang];
  const t = {};
  for (const r of db.query('SELECT key, en, ar FROM texts')) t[r.key] = (lang === 'ar' ? r.ar : r.en) || r.en;
  return textCache[lang] = t;
}
function biz() { return db.query('SELECT * FROM business ORDER BY id LIMIT 1')[0]; }
function round2(n) { return Math.round(n * 100) / 100; }
function money(n) { return round2(n).toFixed(2); }
function loc(row, field, lang) { return (lang === 'ar' && row[field + '_ar'] ? row[field + '_ar'] : row[field]) || ''; }
function fill(s, vars) { return String(s || '').replace(/\{(\w+)\}/g, (m, k) => vars[k] === undefined ? m : String(vars[k])); }
function clip(s, n) { return String(s || '').trim().slice(0, n); }
function nowUTC() { return new Date().toISOString().replace('T', ' ').slice(0, 19); }
// Dates are compared as YYYY-MM-DD in Dubai time (UTC+4).
function dubaiDate(ms) { return new Date(ms + 4 * 3600 * 1000).toISOString().slice(0, 10); }
// An amount with its currency in the page's language, from texts.money: "AED 250.00" or "250.00 د.إ".
function price(n, t) { return (t.money || 'AED {n}').replace('{n}', money(n || 0)); }
// The same for sentences: whole amounts without decimals ("AED 200"), kept on one line.
function amount(n, t) { const v = round2(n || 0); return (t.money || 'AED {n}').replace('{n}', v % 1 === 0 ? String(v) : v.toFixed(2)).replace(/ /g, ' '); }
// 'YYYY-MM-DD' as "19 Nov 2026" or "19 نوفمبر 2026" (month names from texts.months, Western digits).
function longDate(ymd, t) {
  const p = String(ymd || '').slice(0, 10).split('-'), m = String(t.months || '').split('|');
  if (p.length !== 3 || m.length !== 12) return String(ymd || '');
  return Number(p[2]) + ' ' + m[Number(p[1]) - 1] + ' ' + p[0];
}
// A stored UTC time ('YYYY-MM-DD HH:MM:SS') in Dubai time: {day: 'YYYY-MM-DD', text: '19 Nov 2026, 14:05'}.
function dubaiTime(utc, t) {
  const ms = new Date(String(utc || '').replace(' ', 'T') + 'Z').getTime();
  if (!isFinite(ms)) return {day: '', text: String(utc || '')};
  const local = new Date(ms + 4 * 3600 * 1000).toISOString();
  return {day: local.slice(0, 10), text: fill(t.date_time || '{date}, {time}', {date: longDate(local.slice(0, 10), t), time: local.slice(11, 16)})};
}
// Text typed by the owner or a client (often English) isolated inside an Arabic sentence, so its punctuation stays put.
function iso(s, lang) { return lang === 'ar' && s ? '\u2068' + s + '\u2069' : String(s || ''); }
// The Arabic value of a column pair such as name / name_ar, or the English one when there is none.
function pick(row, field, lang) { return loc(row, field, lang); }
// The current address in the other language, keeping the other query parameters (done, error).
function langLink(req, lang) {
  const q = [];
  for (const k in req.query) if (k !== 'lang') q.push(encodeURIComponent(k) + '=' + encodeURIComponent(req.query[k]));
  if (lang === 'ar') q.push('lang=ar');
  return req.path + (q.length ? '?' + q.join('&') : '');
}
function page(req, extra) {
  const lang = langOf(req), b = biz();
  const qs = lang === 'ar' ? '?lang=ar' : '';
  const base = {lang: lang, dir: lang === 'ar' ? 'rtl' : 'ltr', other: lang === 'ar' ? 'en' : 'ar', t: texts(lang), user: req.user, biz: b,
    theme: theme(b), bizName: loc(b, 'name', lang), tagline: loc(b, 'tagline', lang), story: loc(b, 'story', lang), address: loc(b, 'address', lang),
    legalName: loc(b, 'legal_name', lang), licence: loc(b, 'licence', lang),
    path: req.path, qs: qs, lq: qs, amp: lang === 'ar' ? '&lang=ar' : '', here: req.path + qs,
    langEn: langLink(req, 'en'), langAr: langLink(req, 'ar'), wa: (b.whatsapp || '').replace(/[^0-9]/g, '')};
  for (const k in extra) base[k] = extra[k];
  return base;
}
// The enquiry form's fields, so templates never print a missing value.
function formOf(v) {
  const f = {package_id: '', name: '', company: '', phone: '', email: '', message: '', target_date: '', budget: ''};
  for (const k in f) if (v[k]) f[k] = String(v[k]);
  return f;
}
// Documents a client can attach to a quote (documents.label), and how many per quote.
const DOC_LABELS = ['passport', 'emirates_id', 'trade_licence', 'other'];
const MAX_DOCUMENTS = 20;
function notFound(req) { return {template: 'not_found', data: page(req, {}), status: 404}; }
function packageView(p, lang) {
  return {id: p.id, name: loc(p, 'name', lang), description: loc(p, 'description', lang), category: loc(p, 'category', lang),
    price: p.price_from > 0 ? money(p.price_from) : '', priceText: p.price_from > 0 ? price(p.price_from, texts(lang)) : '', priceNum: p.price_from > 0 ? p.price_from : null,
    included: loc(p, 'included', lang).split('\n').map(s => s.trim()).filter(Boolean), duration: loc(p, 'duration', lang), image: p.image || ''};
}
// Quote lines are JSON written by the owner: [{"name": "...", "qty": 1, "price": 1500}]. Returns null when they cannot be used.
function parseLines(raw) {
  let a;
  try { a = JSON.parse(raw || ''); } catch (e) { return null; }
  if (!Array.isArray(a) || a.length === 0 || a.length > 50) return null;
  const out = [];
  for (const l of a) {
    if (!l || typeof l.name !== 'string' || !l.name.trim()) return null;
    if (l.price === null || l.price === undefined || l.price === '') return null;
    const qty = l.qty === undefined || l.qty === null ? 1 : Number(l.qty), price = Number(l.price);
    if (!isFinite(qty) || !isFinite(price) || !(qty > 0) || !(price >= 0)) return null;
    out.push({name: l.name.trim(), qty: qty, price: price});
  }
  return out;
}
// 5% VAT: added on top of the lines, or taken out of them when the business quotes prices including VAT.
function totalsOf(lines, includeVat) {
  const sum = round2(lines.reduce((s, l) => s + l.qty * l.price, 0));
  if (includeVat) { const vat = round2(sum * 5 / 105); return {subtotal: round2(sum - vat), vat: vat, total: sum}; }
  const vat = round2(sum * 0.05);
  return {subtotal: sum, vat: vat, total: round2(sum + vat)};
}
function validUntil(q, b) {
  if (/^\d{4}-\d{2}-\d{2}/.test(q.valid_until || '')) return q.valid_until.slice(0, 10);
  const days = b.quote_valid_days > 0 ? b.quote_valid_days : 14;
  return dubaiDate(new Date(q.created_at.replace(' ', 'T') + 'Z').getTime() + days * 86400000);
}
// What the business holds of a payment row: its amount less what was refunded (SQL, for the paid rows of the ledger).
const HELD = '(amount - coalesce(refunded_amount, 0))';
function paidOf(quoteId) {
  return round2(db.query("SELECT coalesce(SUM" + HELD + ", 0) AS n FROM quote_payments WHERE quote_id = ? AND status = 'paid'", quoteId)[0].n);
}
// Everything the pages need to know about a quote. Money paid always comes from the payments ledger (rows with status paid, less refunds),
// because the owner marks bank transfers paid in the admin panel. paid may be passed to save a query.
function quoteState(q, b, paid) {
  const accepted = q.status === 'accepted' || q.status === 'deposit_paid' || q.status === 'paid';
  const lines = parseLines(accepted && q.accepted_lines ? q.accepted_lines : q.lines);
  let tot = null;
  if (accepted && q.total > 0) tot = {subtotal: q.subtotal, vat: q.vat, total: q.total};
  else if (lines) tot = totalsOf(lines, !!b.prices_include_vat);
  if (!lines || !tot || !(tot.total > 0)) return {ok: false, accepted: accepted, status: q.status};
  let pct = q.deposit_percent === null || q.deposit_percent === undefined ? b.deposit_percent : q.deposit_percent;
  pct = Math.max(0, Math.min(100, Number(pct) || 0));
  const deposit = accepted && q.deposit_amount !== null ? q.deposit_amount : round2(tot.total * pct / 100);
  const until = validUntil(q, b);
  let status = q.status, stage = '', due = 0;
  if (!accepted) paid = 0; else if (paid === undefined) paid = paidOf(q.id);
  if (accepted) {
    status = paid >= tot.total - 0.005 ? 'paid' : paid > 0 ? 'deposit_paid' : 'accepted';
    if (status !== 'paid') {
      // A deposit of 100% is the full payment up front: due at once, like any deposit.
      if (paid === 0 && deposit > 0) { stage = 'deposit'; due = Math.min(deposit, tot.total); }
      else { stage = 'balance'; due = round2(tot.total - paid); }
    }
  } else if (status === 'sent' && until < dubaiDate(Date.now())) status = 'expired';
  return {ok: true, accepted: accepted, status: status, lines: lines, subtotal: tot.subtotal, vat: tot.vat, total: tot.total, pct: pct,
    deposit: deposit, paid: paid, stage: stage, due: due, until: until,
    inclusive: Math.abs(round2(lines.reduce((s, l) => s + l.qty * l.price, 0)) - tot.total) < 0.005};
}
// Brings the stored quote status and paid amount in line with the ledger, so the admin panel shows the same as the client sees.
function syncQuote(q, st) {
  if (!st.ok || !st.accepted) return;
  if (q.status === st.status && Math.abs((q.paid_amount || 0) - st.paid) < 0.005) return;
  db.exec('UPDATE quotes SET status = ?, paid_amount = ? WHERE id = ?', st.status, st.paid, q.id);
}
// A quote with its client, only for the visitor who sent the enquiry, and never a draft.
function ownQuote(id, userId) {
  return db.query(`SELECT q.*, e.user_id AS user_id, e.client_name AS client_name, e.company AS company, e.email AS client_email,
    e.phone AS client_phone, e.lang AS client_lang FROM quotes q JOIN enquiries e ON e.id = q.enquiry_id
    WHERE q.id = ? AND e.user_id = ? AND q.status <> 'draft'`, id, userId)[0];
}
function quoteLink(req, id, lang) { return req.origin + '/quotes/' + id + (lang === 'ar' ? '?lang=ar' : ''); }
function back(id, lang, kind, key) { return {redirect: '/quotes/' + id + '?' + kind + '=' + key + (lang === 'ar' ? '&lang=ar' : '')}; }
// Emails a client in their language; quiet on failure. Returns sent, skipped (no address), limit (too many today) or failed.
// vars are formatted as on the quote page: the amounts total, deposit and amount (numbers) as "AED 4200.00" / "4200.00 د.إ",
// until (YYYY-MM-DD) as "19 Nov 2026" / "19 نوفمبر 2026", and the owner's titles isolated inside Arabic sentences.
function mailClient(to, lang, key, vars) {
  if (!to) return 'skipped';
  lang = lang === 'ar' ? 'ar' : 'en';
  const t = texts(lang);
  vars.business = loc(biz(), 'name', lang);
  for (const k of ['total', 'deposit', 'amount']) if (typeof vars[k] === 'number') vars[k] = price(vars[k], t);
  if (vars.until) vars.until = longDate(vars.until, t);
  for (const k of ['title', 'quote']) if (vars[k]) vars[k] = iso(vars[k], lang);
  try {
    email.send({to: to, subject: fill(t[key + '_subject'], vars).slice(0, 150), text: fill(t[key + '_body'], vars)});
    return 'sent';
  } catch (e) {
    console.warn('email to client not sent: ' + e);
    return String(e).indexOf('too many') >= 0 ? 'limit' : 'failed';
  }
}
function tellOwner(subject, text) {
  try { notify.owner({subject: subject.slice(0, 150), text: text}); } catch (e) { console.warn('owner not notified: ' + e); }
}

lib.notify:
// Tells clients by email about what the owner did in the admin panel: a quote set to sent, the balance asked for, a new
// progress update, a reply, a transfer marked paid; and brings quotes in line with the payments ledger. on_admin_change runs it
// right after each change; the hourly notify_clients job runs it again for emails that hit the daily limit per address.
// Each row has a notified flag that is set once the email is out. At most 10 rows of each kind per run. Returns the emails sent.
function notifyClients(req) {
  const b = biz();
  let sent = 0;
  // done: set the flag unless the address had too many emails today (then the next run tries again).
  const mail = (row, key, vars) => {
    const lang = row.client_lang === 'ar' ? 'ar' : 'en';
    vars.name = row.client_name;
    const r = mailClient(row.client_email, lang, key, vars);
    if (r === 'sent') sent++;
    return r !== 'limit';
  };
  const link = (id, lang) => quoteLink(req, id, lang === 'ar' ? 'ar' : 'en');
  const client = 'e.client_name AS client_name, e.email AS client_email, e.lang AS client_lang';

  // Quotes and their paid amounts follow the ledger (transfers marked paid in the admin panel).
  for (const q of db.query(`SELECT q.*, coalesce((SELECT SUM(p.amount - coalesce(p.refunded_amount, 0)) FROM quote_payments p WHERE p.quote_id = q.id AND p.status = 'paid'), 0) AS ledger
    FROM quotes q WHERE q.status IN ('accepted', 'deposit_paid', 'paid') ORDER BY q.id DESC LIMIT 200`)) {
    const st = quoteState(q, b, round2(q.ledger));
    if (st.ok && (q.status !== st.status || Math.abs((q.paid_amount || 0) - st.paid) >= 0.005)) syncQuote(q, st);
  }

  for (const q of db.query(`SELECT q.*, ${client} FROM quotes q JOIN enquiries e ON e.id = q.enquiry_id
    WHERE q.status = 'sent' AND coalesce(q.notified, 0) = 0 ORDER BY q.id LIMIT 10`)) {
    const st = quoteState(q, b);
    if (!st.ok) { console.warn('quote ' + q.id + ' not announced: its lines cannot be read'); continue; }
    if (st.status === 'expired') { db.exec('UPDATE quotes SET notified = 1 WHERE id = ?', q.id); continue; }
    // The validity starts today when the owner gave no date.
    const until = /^\d{4}-\d{2}-\d{2}/.test(q.valid_until || '') ? q.valid_until.slice(0, 10)
      : dubaiDate(Date.now() + (b.quote_valid_days > 0 ? b.quote_valid_days : 14) * 86400000);
    if (mail(q, 'email_quote', {id: q.id, title: q.title, total: st.total, until: until, link: link(q.id, q.client_lang)})) {
      db.exec('UPDATE quotes SET notified = 1, valid_until = ? WHERE id = ?', until, q.id);
      db.exec("UPDATE enquiries SET status = 'quoted' WHERE id = ? AND status = 'new'", q.enquiry_id);
    }
  }

  for (const q of db.query(`SELECT q.*, ${client} FROM quotes q JOIN enquiries e ON e.id = q.enquiry_id
    WHERE q.balance_due = 1 AND coalesce(q.balance_notified, 0) = 0 AND q.status IN ('accepted', 'deposit_paid') ORDER BY q.id LIMIT 10`)) {
    const st = quoteState(q, b);
    if (!st.ok || st.stage !== 'balance') continue;
    if (mail(q, 'email_balance', {id: q.id, title: q.title, amount: st.due, link: link(q.id, q.client_lang)})) {
      db.exec('UPDATE quotes SET balance_notified = 1 WHERE id = ?', q.id);
    }
  }

  for (const u of db.query(`SELECT u.id, u.title, u.text, u.quote_id, q.title AS quote_title, ${client} FROM updates u JOIN quotes q ON q.id = u.quote_id
    JOIN enquiries e ON e.id = q.enquiry_id WHERE u.visible = 1 AND coalesce(u.notified, 0) = 0 AND q.status <> 'draft' ORDER BY u.id LIMIT 10`)) {
    if (mail(u, 'email_update', {id: u.quote_id, title: u.title, text: u.text || '', quote: u.quote_title, link: link(u.quote_id, u.client_lang)})) {
      db.exec('UPDATE updates SET notified = 1 WHERE id = ?', u.id);
    }
  }

  for (const m of db.query(`SELECT m.id, m.text, m.quote_id, q.title AS quote_title, ${client} FROM messages m JOIN quotes q ON q.id = m.quote_id
    JOIN enquiries e ON e.id = q.enquiry_id WHERE m.sender = 'firm' AND coalesce(m.notified, 0) = 0 AND q.status <> 'draft' ORDER BY m.id LIMIT 10`)) {
    if (mail(m, 'email_message', {id: m.quote_id, text: m.text, quote: m.quote_title, link: link(m.quote_id, m.client_lang)})) {
      db.exec('UPDATE messages SET notified = 1 WHERE id = ?', m.id);
    }
  }

  for (const p of db.query(`SELECT p.id, p.quote_id, p.stage, p.amount, p.paid_at, q.title AS quote_title, ${client} FROM quote_payments p
    JOIN quotes q ON q.id = p.quote_id JOIN enquiries e ON e.id = q.enquiry_id
    WHERE p.status = 'paid' AND coalesce(p.notified, 0) = 0 ORDER BY p.id LIMIT 10`)) {
    const lang = p.client_lang === 'ar' ? 'ar' : 'en';
    if (!p.paid_at) db.exec('UPDATE quote_payments SET paid_at = ? WHERE id = ?', nowUTC(), p.id);
    if (mail(p, 'email_payment', {id: p.quote_id, title: p.quote_title, amount: round2(p.amount), stage: texts(lang)['stage_' + p.stage],
      link: req.origin + '/quotes/' + p.quote_id + '/invoice/' + p.id + (lang === 'ar' ? '?lang=ar' : '')})) {
      db.exec('UPDATE quote_payments SET notified = 1 WHERE id = ?', p.id);
    }
  }
  return sent;
}

